            routerAddress,
            abi.encodeWithSignature("factory()"),
            abi.encode(mockFactory)
        );
        vm.mockCall(
            routerAddress,
            abi.encodeWithSignature("WETH()"),
            abi.encode(mockWETH)
        );

        // Mock factory createPair call
        vm.mockCall(
            mockFactory,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(mockPair)
        );

        // Deploy contract by owner
        vm.startPrank(owner);
        token = new FIFADoge();
        vm.stopPrank();

        // Transfer functionality to functional owner
        vm.prank(owner);
        token.transferOwnership(functionalOwner);
    }

    function test_functional_owner_can_change_swap_settings() public {
        // Confirm current functional ownership
        assertEq(token.owner(), functionalOwner);

        // Functional owner should be able to change settings
        vm.prank(functionalOwner);
        token.setSwapAndLiquifyEnabled(false);

        // Verify state changed correctly
        assertFalse(token.swapAndLiquifyEnabled(), "Functional owner should change state");
    }

    function test_non_functional_owner_cannot_change_settings(address attacker) public {
        vm.assume(attacker != functionalOwner);
        vm.assume(attacker != address(0));

        // Attempt to change settings as non-owner
        vm.prank(attacker);
        vm.expectRevert("Ownable: caller is not the owner");
        token.setSwapAndLiquifyEnabled(false);

        // Verify state remains unchanged
        assertTrue(token.swapAndLiquifyEnabled(), "State should remain unchanged");
    }
}
